import React, { useEffect, useState } from 'react';
import { Container, Spinner } from 'react-bootstrap';
import { getPersons } from '../year_api/YearApi';
import YearPersonCard from '../year_components/YearPersonCard';
import type { YearPerson } from '../year_types/YearTypes';

export default function YearHome() {
  const [persons, setPersons] = useState<YearPerson[] | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let mounted = true;
    getPersons().then(data => {
      if (!mounted) return;
      setPersons(data);
      setLoading(false);
    }).catch(() => {
      if (!mounted) return;
      setPersons([]);
      setLoading(false);
    });
    return () => { mounted = false };
  }, []);

  return (
    <Container style={{ marginTop: '1rem' }}>
      <h1>Персоны</h1>
      {loading && <Spinner animation="border" />}
      {!loading && (!persons || persons.length === 0) && (
        <p>Нет доступных персон.</p>
      )}
      {!loading && persons && (
        <div className="cards-container">
          {persons.map(p => (
            <div key={p.id}>
              <YearPersonCard person={p} />
            </div>
          ))}
        </div>
      )}
    </Container>
  );
}
